type Check = { name: string; status: string; conclusion: string };
type PrState = {
  state: 'OPEN' | 'MERGED' | 'CLOSED'; baseRefName: string; isDraft: boolean;
  mergeable: 'MERGEABLE' | 'CONFLICTING' | 'UNKNOWN'; containsBase: boolean;
  checks: Check[]; // always built by readPr(): `(raw.statusCheckRollup ?? []).map(...)`
};
export function decide(pr: PrState): Action {
  if (pr.state === 'MERGED') return { kind: 'done', why: 'already merged' };
  if (pr.state === 'CLOSED') return { kind: 'stop', why: 'closed without merging' };
  if (pr.baseRefName !== MERGE_BASE) return { kind: 'refuse', why: `base is "${pr.baseRefName}", not "${MERGE_BASE}"` };
  if (pr.isDraft) return { kind: 'refuse', why: 'draft' };
  if (pr.mergeable === 'CONFLICTING') return { kind: 'stop', why: 'conflicts' };
  if (!pr.containsBase) return { kind: 'update', why: 'stale base' };
  if (pr.mergeable === 'UNKNOWN') return { kind: 'wait', why: 'mergeability still computing' };
  if (pr.checks.length === 0) return { kind: 'wait', why: 'no checks reported yet' };
  const running = pr.checks.filter((c) => c.status !== 'COMPLETED');
  const failed = pr.checks.filter((c) => c.status === 'COMPLETED' && !PASSED.has(c.conclusion));
  if (failed.length > 0) return { kind: 'stop', why: 'failed' };
  if (running.length > 0) return { kind: 'wait', why: 'checks running' };
  return { kind: 'merge', why: 'all passed' };
}
